const categories=['All projects','Design','Developer tools','Productivity','Business','Finance','Education','AI & machine learning','Other'];
let state={view:'discover',source:'curated',provider:'all',technology:'All technologies',category:'All projects',query:'',page:1,loading:false};
let discovered=[], catalog=[], searchToken=0, timer, toastTimer;
let session=null, visibleLimit=48, checkedCandidates=0, discoveryWarning='';
const D=RepoDiscovery;const S=RepoStore;const P=RepoProviders;const Q=RepoQuality;const C=RepoCommunity;
let ribbonModes={},detailImage=0,heroIndex=0,heroKey='',editorial={customRows:false,rows:[]},collectionMode='all',lastDetailId=null;
const A=RepoAccount;
const demoCache=readStore('reposhelf.demos.v3',{});
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let collection=readStore('reposhelf.collection.v1',{});if(!collection||typeof collection!=='object'||Array.isArray(collection))collection={};
function persist(){try{localStorage.setItem('reposhelf.collection.v1',JSON.stringify(collection))}catch{toast('Browser storage is unavailable; changes last for this session.')}}
function tracked(){const spaces=Object.fromEntries(Object.entries(collection).filter(([id])=>id.startsWith('hf:')));return {...spaces,...Object.fromEntries([...A.forks].map(([id,row])=>[id,{...row,repo:repoData(id)||row.repo}]))}}
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function protectedLink(url){return '/api/open?url='+encodeURIComponent(safeUrl(url)||'')}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function stars(n){return typeof n==='number'?(n>=1000?(n/1000).toFixed(n>=10000?0:1)+'k':String(n)):'—'}
function repoData(full){return discovered.find(r=>r.full===full)||catalog.find(r=>r.full===full)||curated.find(r=>r.full===full)||A.forks.get(full)?.repo||collection[full]?.repo}
function cover(r){const preview=S.images(r)[0];return `${preview?`<img class="project-preview" src="${escape(preview.src)}" alt="${escape(r.name)} ${preview.kind==='demo'?'demo screenshot':'project image'}" loading="lazy" decoding="async">`:''}`+ `<div class="cover-inner"><span class="cover-logo">${escape(r.symbol||r.name.slice(0,1).toUpperCase())}</span><span class="cover-title">${escape(r.name)}</span></div><span class="cover-kicker">${escape(r.category)}</span>${r.demo?`<span class="live-badge ${Q.demoState(r)?.status==='unavailable'?'demo-broken':''}">${Q.demoState(r)?.status==='unavailable'?'Demo unavailable':Q.demoState(r)?.status==='working'?'Demo checked':'Demo link'}</span>`:''}${tracked()[r.full]?`<span class="fork-badge">${P.isSpace(r)?'Tracked':tracked()[r.full].available===false?'Fork unavailable':'Fork verified'}</span>`:''}`}
function coverStyle(r){return `--cover:${/^#[0-9a-f]{3,8}$/i.test(r.color)?r.color:'#25392f'};--ink:${/^#[0-9a-f]{3,8}$/i.test(r.ink)?r.ink:'#d1e5c5'}`}
function likeButton(r){const selected=A.has(r.full);return `<button class="like-button ${selected?'liked':''}" data-like="${escape(r.full)}" aria-label="${selected?'Unlike':'Like'} ${escape(r.name)}" aria-pressed="${selected}" ${A.busy(r.full)?'disabled':''}><svg width="18" height="18" viewBox="0 0 24 24" fill="${selected?'currentColor':'none'}" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg></button>`}
function savedProjects(){const liked=[...A.liked].map(repoData).filter(Boolean),trackedProjects=Object.values(tracked()).map(x=>x.repo).filter(Boolean);return collectionMode==='likes'?liked:collectionMode==='forks'?trackedProjects:[...new Map([...liked,...trackedProjects].map(r=>[r.full,r])).values()]}
function card(r){const growth=P.isSpace(r)?null:S.trend(r);const action=P.action(r);return `<article class="card"><button class="cover" style="${coverStyle(r)}" data-details="${escape(r.full)}" aria-label="View ${escape(r.name)} details">${cover(r)}</button><div class="card-heading"><h3><button data-details="${escape(r.full)}">${escape(r.name)}</button></h3>${likeButton(r)}</div><p class="card-description">${escape(r.description)}</p>${cardDemoStatus(r)}<div class="tech-tags">${S.technologies(r).slice(0,3).map(t=>`<button data-tech="${escape(t)}">${escape(t)}</button>`).join('')}</div><div class="card-bottom">${P.isSpace(r)?`<span title="Hugging Face likes">♡ ${stars(r.likes)}</span>`:`<span title="GitHub stars">☆ ${stars(r.stars)}</span><span title="GitHub forks">⑂ ${stars(r.forks)}</span>`}${growth?.score>0?`<span class="growth" title="Growth over ${Math.round(growth.days)} days">+${stars(growth.stars)} stars</span>`:''}<button class="fork-button" data-details="${escape(r.full)}">Details</button></div><div class="card-actions">${Q.hasLiveDemo(r)&&D.isAvailable(r)?`<a data-analytics="demo_click" data-project="${escape(r.full)}" data-requires-login="true" href="${escape(protectedLink(r.demo))}" target="_blank" rel="noopener">Try demo ↗</a>`:`<span>${r.demo?'Demo unavailable':'No demo link'}</span>`}${D.isAvailable(r)?`<a class="card-fork" data-analytics="fork_click" data-project="${escape(r.full)}" data-github-fork="${!P.isSpace(r)}" href="${escape(!P.isSpace(r)&&!A.user?'/api/auth?action=start':action.url)}" target="_blank" rel="noopener" title="${escape(action.label)}">${escape(action.short)}</a>${P.isSpace(r)&&P.githubFull(r)?`<a data-analytics="fork_click" data-project="${escape(r.full)}" data-github-fork="true" href="${A.user?'https://github.com/'+escape(P.githubFull(r))+'/fork':'/api/auth?action=start'}" target="_blank" rel="noopener">⑂ Fork</a>`:''}`:`<button data-details="${escape(r.full)}">View tracking</button>`}</div></article>`}
function matching(repos,{category=state.category,query=true}={}){const words=state.query.toLowerCase().trim().split(/\s+/).filter(Boolean);return repos.filter(r=>(state.view==='collection'||D.isAvailable(r))&&P.matchesSource(r,state.provider)&&(!$('#demos').checked||Q.hasLiveDemo(r))&&(category==='All projects'||r.category===category)&&(state.technology==='All technologies'||S.technologies(r).includes(state.technology))&&(!query||r.externalQuery===state.query&&state.remote||words.every(q=>[r.full,r.name,r.description,r.language,...S.technologies(r),(r.topics||[]).join(' ')].some(t=>String(t||'').toLowerCase().includes(q)))))}
function order(repos,sort=$('#sort').value){if(['popular','featured','trending'].includes(sort))return sort==='trending'?S.sorted(repos.filter(r=>!P.isSpace(r)),'trending'):P.popular(repos);const list=[...repos];if(sort==='releases')return list.filter(r=>S.recentRelease(r)).sort((a,b)=>Date.parse(b.latestRelease.publishedAt)-Date.parse(a.latestRelease.publishedAt));if(sort==='stars')list.sort((a,b)=>(b.stars??-1)-(a.stars??-1));if(sort==='forks')list.sort((a,b)=>(b.forks??-1)-(a.forks??-1));if(sort==='newest')list.sort((a,b)=>new Date(b.created||0)-new Date(a.created||0));if(sort==='updated')list.sort((a,b)=>new Date(b.updated||0)-new Date(a.updated||0));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list}
function ribbon(title,items,{category='All projects',rank='popular',caption='',controls=false,community=false,custom=false,limit=12}={}){return `<section class="ribbon"><div class="ribbon-heading"><div><h3>${escape(title)}</h3>${caption?`<p>${escape(caption)}</p>`:''}</div><div class="ribbon-options">${controls?`<button data-ribbon-rank="popular" data-ribbon-category="${escape(category)}" class="${rank==='popular'?'active':''}">Popular</button><button data-ribbon-rank="trending" data-ribbon-category="${escape(category)}" class="${rank==='trending'?'active':''}">Trending</button>`:''}${community||custom?'':`<button class="view-all" data-view-all="${escape(category)}" data-rank="${rank}">View all</button>`}</div></div>${items.length?`<div class="ribbon-track">${items.slice(0,limit).map(community?communityCard:card).join('')}</div>`:`<p class="ribbon-empty">${community?'No recent discussions match these filters yet.':rank==='trending'?'Measured trends will appear once we have at least a day of star and fork history.':'No projects match these filters yet.'}</p>`}</section>`}
function editorialRows(pool){return editorial.rows.filter(row=>row.enabled).map(row=>{let repos=row.mode==='manual'?row.items.map(repoData).filter(Boolean):pool;repos=matching(repos);if(row.category)repos=repos.filter(r=>r.category===row.category);if(row.mode!=='manual')repos=order(repos,row.mode);return ribbon(row.title,repos,{category:row.category||'All projects',rank:row.mode==='manual'?'popular':row.mode,caption:row.description,custom:true,limit:row.mode==='manual'?120:12})}).join('')}
async function loadEditorial(){try{const response=await fetch('/api/editorial',{signal:AbortSignal.timeout(10000)});if(!response.ok)return;const data=await response.json();if(typeof data.customRows==='boolean'&&Array.isArray(data.rows)){editorial=data;render()}}catch{}}
function renderRibbons(){const pool=matching(catalog);const picks=matching(curated);let html=ribbon('Editor’s picks',picks,{caption:'A small selection chosen for what you can build.',rank:'popular'});html+=ribbon('Community discoveries',C.rank(pool),{community:true,caption:'Recent repository discussions on Hacker News and Bluesky. Ranked by community interest and recency.'});html+=ribbon('Popular recent releases',P.popular(pool.filter(r=>S.recentRelease(r))),{caption:'Published GitHub releases from the last 30 days.',rank:'releases'});html+=ribbon('Trending now',S.sorted(pool.filter(r=>!P.isSpace(r)),'trending'),{caption:'Measured growth in stars and forks. Each card shows its observation window.',rank:'trending'});if(editorial.customRows){html+=editorialRows(pool);$('#ribbons').innerHTML=html;return}for(const category of categories.slice(1)){if(state.category!=='All projects'&&category!==state.category)continue;const available=pool.filter(r=>r.category===category);if(!available.length)continue;const rank=ribbonModes[category]||'popular';html+=ribbon(category,rank==='trending'?S.sorted(available.filter(r=>!P.isSpace(r)),rank):P.popular(available),{category,rank,controls:true,caption:rank==='popular'?'Popularity within each source: GitHub stars and forks, or Space likes.':'Ranked by measured growth.'})}$('#ribbons').innerHTML=html}
function renderHero(){const visible=state.view==='discover'&&state.source==='curated'&&!state.query&&state.category==='All projects'&&state.technology==='All technologies';const picks=matching(curated),items=(picks.length?picks:P.popular(matching(catalog))).slice(0,5);$('#hero').hidden=!visible||!items.length;if(!visible||!items.length)return;const key=items.map(r=>r.full+':'+(S.images(r)[0]?.src||'')).join('|');if(key!==heroKey){heroIndex=0;heroKey=key;$('#hero-track').innerHTML=items.map((r,i)=>{const image=S.images(r)[0];return `<article class="hero-slide" style="${coverStyle(r)}" role="group" aria-roledescription="slide" aria-label="${i+1} of ${items.length}: ${escape(r.name)}"><div class="hero-copy"><p class="hero-eyebrow">${escape(r.category)} · Featured project</p><h2><button data-details="${escape(r.full)}">${escape(r.name)}</button></h2><p class="hero-description">${escape(r.description)}</p><div class="hero-actions">${Q.hasLiveDemo(r)?`<a class="button lime" data-analytics="demo_click" data-project="${escape(r.full)}" data-requires-login="true" href="${escape(protectedLink(r.demo))}" target="_blank" rel="noopener">Try demo ↗</a>`:''}<button class="button outline" data-details="${escape(r.full)}">View project</button></div></div><button class="hero-visual ${image?'has-preview':''}" data-details="${escape(r.full)}" aria-label="View ${escape(r.name)} details">${image?`<img src="${escape(image.src)}" alt="${escape(r.name)} ${image.kind==='demo'?'demo screenshot':'project preview'}" loading="${i?'lazy':'eager'}" decoding="async">`:`<span class="hero-monogram">${escape(r.symbol||r.name.slice(0,1).toUpperCase())}</span><span class="hero-preview-name">${escape(r.name)}</span>`}</button></article>`}).join('');$('#hero-track').scrollLeft=0}}
function moveHero(step){const track=$('#hero-track'),slides=[...track.children];if(!slides.length)return;heroIndex=Math.max(0,Math.min(slides.length-1,heroIndex+step));const left=slides[heroIndex].offsetLeft-slides[0].offsetLeft;track.scrollTo({left,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function render(){
$('#fork-count').textContent=new Set([...Object.keys(tracked()),...A.liked]).size;
$('#collection-tabs').hidden=state.view!=='collection';$('#collection-tabs').innerHTML=['all','likes','forks'].map(mode=>`<button data-collection-mode="${mode}" class="${mode===collectionMode?'active':''}">${mode==='all'?'All saved':mode==='likes'?'Liked':'Forks & Spaces'}</button>`).join('');
$('#section-heading').textContent=state.view==='collection'?'Your collection':'Browse projects';

const filters=[$('#demos').checked?'Live demos only':null,state.provider==='all'?null:state.provider==='github'?'GitHub':'Hugging Face',$('#sort').value==='popular'?null:$('#sort').selectedOptions[0].textContent].filter(Boolean);$('#filter-count').hidden=!filters.length;$('#filter-count').textContent=`${filters.length} active`;$('#filter-count').title=filters.join(' · ');const filterButton=$('#more-filters summary');filterButton.dataset.active=String(Boolean(filters.length));filterButton.setAttribute('aria-label',filters.length?`Filters, ${filters.length} active: ${filters.join(', ')}`:'Filters');filterButton.title=filters.length?`Filters: ${filters.join(' · ')}`:'Filters';$('#clear-source').hidden=state.provider==='all';$('.source-control').hidden=state.view==='collection';$('#channels').hidden=state.view==='collection';renderHero();
document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false')});
$('#curated').classList.toggle('active',state.source==='curated');$('#github').classList.toggle('active',state.source==='github');
$('.categories').innerHTML=categories.map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c==='All projects'?'All':c}</button>`).join('');
$('#channels').innerHTML=S.channels.map(t=>`<button class="channel ${state.technology===t?'active':''}" data-tech="${escape(t)}" aria-pressed="${state.technology===t}"><span>${t==='All technologies'?'◈':escape(t==='Three.js'?'3D':t==='Node.js'?'N':t.slice(0,2))}</span>${escape(t)}</button>`).join('');
const storefront=state.view==='discover'&&state.source==='curated'&&!state.query;
let repos=order(matching(state.view==='collection'?savedProjects():state.source==='curated'?catalog:discovered));
$('#ribbons').hidden=!storefront;$('#grid').hidden=storefront;if(storefront)renderRibbons();
$('#result-count').textContent=`${repos.length.toLocaleString()} project${repos.length===1?'':'s'}${$('#demos').checked?' with live demos':''}`;
$('#data-note').textContent=state.view==='collection'?(A.user?'Likes and verified forks synced to your account':'Sign in to save likes and verify public forks'):`${catalog.filter(D.isAvailable).length.toLocaleString()} indexed${checkedCandidates?' · '+checkedCandidates.toLocaleString()+' checked live':''}`;
$('#grid').innerHTML=repos.slice(0,visibleLimit).map(card).join('')||`<div class="empty"><h3>${state.loading?'Finding your next project…':state.view==='collection'&&!savedProjects().length?'Your next project starts here.':'No projects found'}</h3><p>${state.loading?'Checking repository README files for live demo links.':state.view==='collection'&&!savedProjects().length?'Sign in with GitHub to save likes and see your verified public forks across devices.':$('#sort').value==='trending'?'Trending requires measured star and fork growth. Choose Popular while history accumulates.':'Try a different search or technology, or switch off “Live demos only”.'}</p>${!state.loading?'<button class="button outline" id="reset-filters">Reset filters</button>':''}</div>`;
const moreLocal=repos.length>visibleLimit;$('#search-external').hidden=storefront||state.view==='collection'||state.provider==='huggingface';$('#search-external').disabled=state.loading;$('#search-external').textContent=state.loading?'Checking GitHub…':state.remote&&hasMore()?'Find more on GitHub':'Search beyond the catalog on GitHub';
$('#load-more').hidden=storefront||!moreLocal;$('#load-more').disabled=false;$('#load-more').textContent='Show more projects';
$('#account-button span:last-child').textContent=A.user?`@${A.user.name}`:'Sign in';
}
function reportDemoUrl(r){const u=new URL('https://github.com/sparx1981/RepoShelf/issues/new');u.searchParams.set('template','broken-demo.md');u.searchParams.set('title',`[Broken demo] ${r.name}`);u.searchParams.set('body',`Project: \`${r.full}\`
Demo: ${r.demo}

What happened?

When did you try it?

Last recorded check: ${Q.demoState(r)?.checkedAt||'Not checked yet'}

Reports are reviewed through independent checks; a report alone does not remove a project.`);return u.href}
function communityCard(r){const latest=[];for(const p of C.posts(r)){if(!latest.some(x=>x.source===p.source))latest.push(p)}const links=latest.map(p=>`<a href="${escape(C.postUrl(p))}" target="_blank" rel="noopener" title="Open the original ${p.source==='hackernews'?'Hacker News':'Bluesky'} discussion">${p.source==='hackernews'?'Hacker News':'Bluesky'} · ${escape(new Date(p.publishedAt).toLocaleDateString(undefined,{month:'short',day:'numeric'}))} ↗</a>`).join('');return card(r).replace('</article>',`<div class="community-card-links">${links}</div></article>`)}
function communityInfo(r){const posts=C.posts(r);if(!posts.length)return '';return `<section class="community-details" aria-label="Community discussions"><h3>Community discussions</h3><p class="small">Recent public posts linking to this repository. These discussions are separate from GitHub popularity.</p><ul>${posts.slice(0,8).map(p=>`<li><a href="${escape(C.postUrl(p))}" target="_blank" rel="noopener"><span>${p.source==='hackernews'?'Hacker News':'Bluesky'}</span> ${escape(p.title)} ↗</a><p>${escape(p.authorName||p.author||'Public discussion')} · <time datetime="${escape(p.publishedAt)}">${escape(new Date(p.publishedAt).toLocaleDateString())}</time> · ${p.source==='hackernews'?`${stars(p.points||0)} points · ${stars(p.comments||0)} comments`:p.engagementKnown===false?'Engagement not fetched':`${stars(p.likes||0)} likes · ${stars(p.replies||0)} replies · ${stars(p.reposts||0)} reposts`}</p></li>`).join('')}</ul>${posts.length>8?`<p class="small">Showing the eight most recent of ${posts.length} saved discussions.</p>`:''}</section>`}
function cardDemoStatus(r){if(!r.demo)return '';const h=Q.demoState(r);return `<p class="demo-check-line ${h?.status==='unavailable'?'unavailable':''}">${escape(Q.demoLabel(r))}${h?.checkedAt?' · '+escape(new Date(h.checkedAt).toLocaleDateString()):''}</p>`}
function demoInfo(r){if(!r.demo)return '';const h=Q.demoState(r),notes=h?.status==='working'?'The demo page loaded successfully. Interactive features have not been tested.':h?.status==='unavailable'?'The demo failed two separate checks and is excluded from demo-only results until it recovers.':h?.status==='review'?'One check reported an unavailable page. We will check again before excluding it.':'This demo has not yet had a conclusive check.';return `<section class="demo-health-panel" aria-label="Demo availability"><div><h3>${escape(Q.demoLabel(r))}</h3>${h?.checkedAt?`<p>Checked <time datetime="${escape(h.checkedAt)}">${escape(new Date(h.checkedAt).toLocaleString())}</time></p>`:''}</div><p>${escape(notes)}</p>${h?.error?'<p class="small">The latest attempt was inconclusive. The saved result is retained for a later retry.</p>':''}<div class="demo-report-actions"><a id="report-demo" href="${escape(reportDemoUrl(r))}" target="_blank" rel="noopener">Report a broken demo ↗</a>${h?.status==='unavailable'?`<a data-analytics="demo_click" data-project="${escape(r.full)}" data-requires-login="true" href="${escape(protectedLink(r.demo))}" target="_blank" rel="noopener">Open original demo link ↗</a>`:''}</div><p class="small">Reporting opens a prefilled GitHub issue. It requires a GitHub account.</p></section>`}
function reuseGuide(r){const i=r.projectInsights,licence=Q.licenseInfo(r),purpose=i?.whatItDoes?.text,audience=Array.isArray(i?.audience)?i.audience.slice(0,2):[],requirements=Array.isArray(i?.requirements)?i.requirements.slice(0,6):[];const titles={account:'Account',api_key:'External API key',paid_service:'Paid service',hosting:'Self-hosting'},statuses={required:'Required',optional:'Optional',not_required:'Not required',documented:'Documented'};return `<section class="reuse-guide" aria-label="Reuse information"><h3>Before you make it your own</h3>${purpose&&purpose!==r.description?`<div class="reuse-fact"><h4>What it does</h4><p>${escape(purpose)}</p></div>`:''}<div class="reuse-fact"><h4>Who it’s for</h4>${audience.length?audience.map(a=>`<p>${escape(a.text)}</p>`).join(''):'<p class="unknown-fact">The intended audience has not been extracted from the author’s description.</p>'}</div><div class="reuse-fact"><h4>Running your own copy</h4>${requirements.length?`<ul class="requirements">${requirements.map(x=>`<li><span class="requirement-tag">${escape(titles[x.kind]||'Requirement')} · ${escape(statuses[x.status]||'Documented')}</span><p>${escape(x.text)}</p></li>`).join('')}</ul>`:'<p class="unknown-fact">Account, service, and hosting requirements have not been extracted yet. This does not mean there are none.</p>'}${i?.sourceUrl?`<a class="overview-link" href="${escape(safeUrl(i.sourceUrl))}" target="_blank" rel="noopener">Author’s setup documentation ↗</a>`:''}<p class="small">${P.isSpace(r)?'Duplicating this Space requires a Hugging Face account.':'Forking this repository requires a GitHub account.'} Browsing and saving projects here does not.</p></div><div class="reuse-fact licence-guide"><h4>${escape(licence.id||'Licence not specified')}</h4><span class="requirement-tag">${escape(licence.title)}</span><p>${escape(licence.text)}</p>${licence.url?`<a class="overview-link" href="${escape(licence.url)}" target="_blank" rel="noopener">Full licence terms ↗</a>`:''}<a class="overview-link" href="${escape(P.repositoryUrl(r))}" target="_blank" rel="noopener">Review the project’s declared licence ↗</a><p class="small">A short guide to the declared licence; check which files and assets it covers.</p></div></section>`}
function aiOverview(r){const ai=r.aiOverview;if(!ai||!Array.isArray(ai.paragraphs)||!ai.paragraphs.length)return '';return `<section class="ai-overview" aria-label="AI overview"><h3>AI-generated overview</h3><p class="overview-source">Gemini · ${escape(new Date(ai.generatedAt).toLocaleDateString())} · Based on author-provided information</p>${ai.paragraphs.slice(0,2).map(p=>`<p>${escape(p.text)}</p>`).join('')}<details><summary>Sources for this summary</summary>${ai.paragraphs.flatMap(p=>p.evidenceQuotes||[]).slice(0,6).map(q=>`<blockquote>${escape(q)}</blockquote>`).join('')}${ai.sourceUrl?`<a class="overview-link" href="${escape(safeUrl(ai.sourceUrl))}" target="_blank" rel="noopener">Read the original source ↗</a>`:''}</details></section>`}
function projectOverview(r){const overview=r.overview;if(overview?.kind!=='readme')return '';const paragraphs=Array.isArray(overview.paragraphs)?overview.paragraphs.filter(p=>typeof p==='string'&&p.trim()&&p.trim().toLowerCase()!==String(r.description||'').trim().toLowerCase()&&p!==r.projectInsights?.whatItDoes?.text).slice(0,3):[];const features=Array.isArray(overview.features)?overview.features.filter(p=>typeof p==='string'&&p.trim()).slice(0,5):[];if(!paragraphs.length&&!features.length)return '';const source=safeUrl(overview.sourceUrl);return `<section class="project-overview" aria-label="Project overview"><h3>About this project</h3><p class="overview-source">From the project’s README · Author-written excerpt</p>${paragraphs.map(p=>`<p>${escape(p)}</p>`).join('')}${features.length?`<h4>Features from the README</h4><ul>${features.map(f=>`<li>${escape(f)}</li>`).join('')}</ul>`:''}${source?`<a class="overview-link" href="${escape(source)}" target="_blank" rel="noopener">Read the full README ↗</a>`:''}</section>`}
function showDetails(full){const r=repoData(full);if(!r)return;if(!$('#detail').open||lastDetailId!==full){A.track('listing_view',full);lastDetailId=full;}const entry=tracked()[full],url=P.repositoryUrl(r),action=P.action(r),images=S.images(r),growth=P.isSpace(r)?null:S.trend(r);detailImage=Math.min(detailImage,Math.max(0,images.length-1));const image=images[detailImage];
$('#detail-content').innerHTML=`<p class="eyebrow">${escape(r.category)} · ${D.isAvailable(r)?P.isSpace(r)?'HUGGING FACE SPACE':'PUBLIC GITHUB REPOSITORY':'UNAVAILABLE'}</p><div class="detail-gallery">${image?`<img class="detail-preview" src="${escape(image.src)}" alt="${escape(r.name)} ${image.kind==='demo'?'demo screenshot':'project image'}"><p class="preview-caption">${image.kind==='demo'?'Captured from the live demo':'Project image from the README'}${image.capturedAt?' · '+escape(new Date(image.capturedAt).toLocaleDateString()):''}</p>`:`<div class="cover" style="${coverStyle(r)}">${cover(r)}</div><p class="preview-caption">A screenshot is not available for this project yet.</p>`}${images.length>1?`<div class="gallery-thumbs">${images.map((i,n)=>`<button data-gallery="${n}" data-repo="${escape(full)}" class="${n===detailImage?'active':''}" aria-label="Show image ${n+1}"><img src="${escape(i.src)}" alt="Preview ${n+1}" loading="lazy"></button>`).join('')}</div>`:''}</div><div class="detail-title"><h2>${escape(r.name)}</h2>${likeButton(r)}</div><p class="repo-owner">${escape(r.full)}</p><p>${escape(r.description)}</p><div class="tech-tags detail-tags">${S.technologies(r).map(t=>`<button data-tech="${escape(t)}">${escape(t)}</button>`).join('')}${r.language?`<span>${escape(r.language)}</span>`:''}</div><div class="detail-actions">${Q.hasLiveDemo(r)&&D.isAvailable(r)?`<a class="button lime" data-analytics="demo_click" data-project="${escape(r.full)}" data-requires-login="true" href="${escape(protectedLink(r.demo))}" target="_blank" rel="noopener">Try demo ↗</a>`:''}${D.isAvailable(r)?`<a class="button outline" data-analytics="fork_click" data-project="${escape(r.full)}" data-github-fork="${!P.isSpace(r)}" href="${escape(!P.isSpace(r)&&!A.user?'/api/auth?action=start':action.url)}" target="_blank" rel="noopener">${escape(action.label)}</a>`:''}${P.isSpace(r)&&P.githubFull(r)?`<a class="button outline" data-analytics="fork_click" data-project="${escape(r.full)}" data-github-fork="true" href="${A.user?'https://github.com/'+escape(P.githubFull(r))+'/fork':'/api/auth?action=start'}" target="_blank" rel="noopener">Fork source on GitHub</a>`:''}<a class="button outline" data-requires-login="true" href="${escape(protectedLink(url))}" target="_blank" rel="noopener">Repository</a></div>${demoInfo(r)}${communityInfo(r)}${reuseGuide(r)}${aiOverview(r)}${projectOverview(r)}<dl class="project-facts">${P.isSpace(r)?`<div><dt>Space likes</dt><dd>${stars(r.likes)}</dd></div><div><dt>Runtime</dt><dd>${escape(r.runtime)}</dd></div>`:`<div><dt>Stars</dt><dd>${stars(r.stars)}</dd></div><div><dt>Forks</dt><dd>${stars(r.forks)}</dd></div>`}<div><dt>Latest release</dt><dd>${r.latestRelease?`<a href="${escape(safeUrl(r.latestRelease.url)||url)}" target="_blank" rel="noopener">${escape(r.latestRelease.tag||r.latestRelease.name)}</a><small>${escape(new Date(r.latestRelease.publishedAt).toLocaleDateString())}</small>`:r.releaseCheckedAt?'No published release':'Not checked yet'}</dd></div><div><dt>Last code update</dt><dd>${r.updated?escape(new Date(r.updated).toLocaleDateString()):'Not available'}</dd></div><div><dt>Availability check</dt><dd>${r.lastCheckedAt?escape(new Date(r.lastCheckedAt).toLocaleDateString()):'Not checked yet'}${r.checkError?'<small>Latest attempt will be retried</small>':''}</dd></div></dl>${growth?`<p class="growth-detail">+${stars(growth.stars)} stars · +${stars(growth.forks)} forks over ${Math.round(growth.days)} days</p>`:''}<p class="small">${r.demo?'Demo checks confirm that a public page loaded at the recorded time. They do not test every feature.':'No confirmed live demo.'} Check the license before reusing code.</p>${r.spaces?.length?`<p class="small">Also on Hugging Face: ${r.spaces.map(x=>`<a href="${escape(x.url)}" target="_blank" rel="noopener">${escape(x.id)}</a>`).join(', ')}</p>`:''}${r.discoveredVia?.length?`<p class="small">Discovered via ${r.discoveredVia.map(x=>`<a href="${escape(safeUrl(x.url))}" target="_blank" rel="noopener">${escape(x.name)}</a>`).join(', ')}. Demo link checked independently.</p>`:''}<div class="tracking"><p>${P.isSpace(r)?'Duplication opens Hugging Face and requires its own account. Space tracking stays in this browser.':entry?(entry.available===false?'This saved public fork is currently unavailable. A later sync can restore it.':'Public fork verified for your signed-in GitHub account.'):A.user?'Create your fork on GitHub, then check here to verify it.':'Sign in with GitHub to fork and track this project across devices.'}</p>${P.isSpace(r)?`<button class="button ${entry?'outline':'lime'}" id="track-repo">${entry?'Remove tracking':'Save this Space'}</button>`:`<button class="button outline" id="verify-forks" ${A.syncing?'disabled':''}>${A.user?A.syncing?'Checking forks…':'Check my public forks':'Sign in with GitHub'}</button>`}</div>${entry?.url?`<p><a href="${escape(safeUrl(entry.url)||url)}" target="_blank" rel="noopener">Open my fork ↗</a></p>`:''}`;
if($('#track-repo'))$('#track-repo').onclick=()=>{if(collection[full]){delete collection[full];toast('Space removed')}else{collection[full]={repo:r,verified:false,added:new Date().toISOString()};toast('Space saved in this browser.')}persist();render();showDetails(full)};
if($('#verify-forks'))$('#verify-forks').onclick=()=>{if(!A.user){openAccount();return}void syncForks()}
;if(!$('#detail').open)$('#detail').showModal()}
async function api(path){const res=await fetch(`https://api.github.com${path}`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(12000)});if(!res.ok){if(res.status===403||res.status===429)throw new Error('GitHub’s public API limit was reached.');if(res.status===404)throw new Error('GitHub could not find that public account or repository.');throw new Error(`GitHub is unavailable (${res.status}). Please try again.`)}return res.json()}
async function pool(items,fn,limit=4){let i=0;return Promise.all(Array.from({length:Math.min(limit,items.length)},async()=>{while(i<items.length){const n=i++;await fn(items[n],n)}}))}
async function hydrate(){let loaded=0;try{await pool(curated,async r=>{try{const d=await api(`/repos/${r.full}`);Object.assign(r,{stars:d.stargazers_count,forks:d.forks_count,created:d.created_at,updated:d.pushed_at,license:d.license?.spdx_id==='NOASSERTION'?null:d.license?.spdx_id});loaded++;if(collection[r.full])collection[r.full].repo=r}catch{}});render();if(!loaded&&state.source==='curated'&&state.view==='discover')$('#status').textContent='Live GitHub statistics are unavailable. You can still browse projects, open demos, and track forks.'}catch{}}
function classify(r){return D.classify(r)}
async function findDemo(repo){const key=repo.full.toLowerCase(),cached=demoCache[key];if(cached&&cached.updated===repo.updated&&Date.now()-cached.checked<7*86400000)return cached.demo;
let content=null;for(const path of ['README.md','readme.md','README.MD']){try{const res=await fetch(`https://raw.githubusercontent.com/${repo.full}/${encodeURIComponent(repo.branch||'main')}/${path}`,{signal:AbortSignal.timeout(7000)});if(res.status===404)continue;if(!res.ok)throw new Error('README temporarily unavailable');content=await res.text();break}catch{return undefined}}
const demo=D.extractDemo(content,repo.homepage);demoCache[key]={updated:repo.updated,checked:Date.now(),demo};return demo;}
function saveDemoCache(){try{const recent=Object.entries(demoCache).sort((a,b)=>b[1].checked-a[1].checked).slice(0,3000);localStorage.setItem('reposhelf.demos.v3',JSON.stringify(Object.fromEntries(recent)))}catch{}}
function hasMore(){return Boolean(session?.queries.some(q=>!q.done))}
function mergeRepos(items){const repos=new Map(discovered.map(r=>[r.full.toLowerCase(),r]));for(const r of items){const key=r.full.toLowerCase();repos.set(key,{...repos.get(key),...r})}discovered=[...repos.values()]}
function useCatalog(){searchToken++;state.loading=false;state.remote=false;session=null;visibleLimit=48;checkedCandidates=0;discovered=[...catalog];$('#status').textContent='';render()}
async function loadCatalog(){const read=async path=>{const res=await fetch(path,{signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error('Catalog unavailable');return res.json()};const results=await Promise.allSettled([read('catalog.json'),read('spaces.json'),read('community.json')]);const data=results[0].status==='fulfilled'?results[0].value:{repositories:[]};const spaces=results[1].status==='fulfilled'?results[1].value:{repositories:[]};const all=new Map(curated.map(r=>[r.full.toLowerCase(),r]));for(const r of data.repositories||[])if(P.validId(r.full)&&typeof r.name==='string'&&(!r.demo||D.demoUrl(r.demo)))all.set(r.full.toLowerCase(),r);for(const r of curated){const saved=all.get(r.full.toLowerCase());if(saved)Object.assign(r,saved)}catalog=C.attach(P.mergeCatalog([...all.values()],(spaces.repositories||[]).filter(r=>P.isSpace(r)&&P.validId(r.spaceId)&&r.full===`hf:${r.spaceId}`&&typeof r.name==='string'&&(!r.demo||r.demo===P.repositoryUrl(r)))).map(r=>({...r,technologies:S.technologies(r)})),results[2].status==='fulfilled'?results[2].value.mentions:[]);useCatalog();if(results[0].status==='rejected')$('#status').textContent='The saved catalog is temporarily unavailable. Editor’s picks are still available.'}
async function discover(append=false){const token=++searchToken;if(!append){state.remote=true;visibleLimit=48;checkedCandidates=0;discoveryWarning='';session={queries:D.searchQueries({query:state.query,category:state.category,technology:state.technology,demos:$('#demos').checked,newest:$('#sort').value==='newest'}).map(q=>({q,page:1,done:false})),next:0};discovered=[...catalog]}
state.loading=true;$('#status').textContent='Searching GitHub and checking demo links…';render();let temporaryFailures=0;
try{for(let batch=0;batch<3&&hasMore();batch++){if(token!==searchToken)return;let task;for(let i=0;i<session.queries.length;i++){const index=session.next++%session.queries.length;if(!session.queries[index].done){task=session.queries[index];break}}if(!task)break;
const sort=$('#sort').value==='updated'?'updated':$('#sort').value==='forks'?'forks':'stars';const data=await api(`/search/repositories?q=${encodeURIComponent(task.q)}&sort=${sort}&order=desc&per_page=100&page=${task.page}`);if(token!==searchToken)return;task.page++;task.done=data.items.length<100||(task.page-1)*100>=Math.min(data.total_count??1000,1000);
const existing=new Map([...catalog,...discovered].map(r=>[r.full.toLowerCase(),r]));const results=data.items.map(d=>({...D.mapRepo(d),externalQuery:state.query}));await pool(results,async r=>{if(token!==searchToken)return;const known=existing.get(r.full.toLowerCase());if(known?.demo&&D.isAvailable(known))Object.assign(r,{demo:known.demo,name:known.name,color:known.color,ink:known.ink,symbol:known.symbol,screenshots:known.screenshots,latestRelease:known.latestRelease,releaseCheckedAt:known.releaseCheckedAt,technologies:known.technologies,metrics:known.metrics,lastCheckedAt:known.lastCheckedAt});else{const demo=await findDemo(r);if(demo===undefined)temporaryFailures++;else r.demo=demo;}if(token!==searchToken)return;checkedCandidates++;mergeRepos([r]);if(checkedCandidates%8===0)render()},8);if(token!==searchToken)return;saveDemoCache();render();const matches=matching(discovered);if(matches.length>=24)break;}
if(token!==searchToken)return;$('#status').textContent=`Checked ${checkedCandidates.toLocaleString()} repositories for demo links.${temporaryFailures?' Some READMEs could not be reached; they have not been marked as having no demo.':''}${hasMore()?' Keep exploring to search additional batches.':' All results in this search have been checked.'}${$('#sort').value==='newest'?' Newest live search covers the last 30 days; creation-date sorting applies to loaded results.':''}`;
}catch(e){if(token!==searchToken)return;discoveryWarning=e.message||'Could not reach GitHub.';$('#status').textContent=`${discoveryWarning} Your catalog matches are still shown. Retry with the GitHub search button later.`}finally{if(token===searchToken){state.loading=false;render()}}}
async function syncForks(){try{const result=await A.syncForks();toast(result?.message||'Forks checked.')}catch(e){toast(e.message)}finally{renderAccount();render();if($('#detail').open&&lastDetailId)showDetails(lastDetailId)}}
function renderAccount(){const person=A.user;$('#account-auth').innerHTML=person?`<p>Signed in as <strong>${escape(person.name)}</strong>. Likes and verified public forks sync across devices.</p><div class="account-actions">${person.admin?'<a class="button lime" href="/admin.html">Administration ↗</a><a class="button outline" href="/admin.html?tab=users">Manage users</a><a class="button outline" href="/admin.html?tab=sync">Sync log</a><a class="button outline" href="/admin.html?tab=help">Help</a>':''}${A.guestCount?`<button class="button outline" id="import-likes">Import ${A.guestCount} browser likes</button>`:''}<button class="button outline" id="signout">Sign out</button></div><h3>Public forks</h3><p>Verified against your signed-in GitHub account. Private forks are not accessible.</p><button class="button lime" id="sync-forks" ${A.syncing?'disabled':''}>${A.syncing?'Checking forks…':A.forkSync.inProgress?'Continue checking forks':'Check my public forks'}</button><p class="small">${A.forkSync.completedAt?'Last completed scan: '+escape(new Date(A.forkSync.completedAt).toLocaleString()):'Checks run in resumable batches. Saved forks remain available across devices.'}</p><p role="status">${escape(A.forkError||'')}</p>`:A.enabled?'<p>Sign in with GitHub to like projects, fork them, and see your verified public forks across devices.</p><a class="button lime" href="/api/auth?action=start">Sign in with GitHub ↗</a>':'<p>GitHub sign-in is awaiting configuration. You can still browse projects and try demos.</p>';if($('#signout'))$('#signout').onclick=async()=>{try{await A.signout();toast('Signed out. Your saved account collection is safe.')}catch(e){toast(e.message)}};if($('#sync-forks'))$('#sync-forks').onclick=()=>void syncForks();if($('#import-likes'))$('#import-likes').onclick=async e=>{e.target.disabled=true;try{await A.importGuest();toast('Browser likes imported into your account.')}catch(e){toast(e.message)}finally{renderAccount()}}}
window.addEventListener('reposhelf-account',()=>{renderAccount();render();if($('#detail').open&&lastDetailId)showDetails(lastDetailId)});
function openAccount(){renderAccount();if(!$('#account').open)$('#account').showModal()}
$('#account-button').onclick=openAccount;
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('click',e=>{const like=e.target.closest('[data-like]');if(like){if(!A.user){openAccount();return}void A.toggle(like.dataset.like).catch(err=>toast(err.message));return}const mode=e.target.closest('[data-collection-mode]');if(mode){collectionMode=mode.dataset.collectionMode;render();return}const gated=e.target.closest('[data-requires-login]');if(gated&&!A.user?.githubConnected){e.preventDefault();openAccount();return}const analytic=e.target.closest('[data-analytics]');if(analytic&&analytic.dataset.analytics==='fork_click'&&analytic.dataset.githubFork==='true'&&!A.user){e.preventDefault();openAccount();return}if(analytic)A.track(analytic.dataset.analytics,analytic.dataset.project);if($('#more-filters').open&&!e.target.closest('#more-filters'))$('#more-filters').open=false;const heroStep=e.target.closest('[data-hero-step]');if(heroStep)moveHero(Number(heroStep.dataset.heroStep));const details=e.target.closest('[data-details]');if(details){detailImage=0;showDetails(details.dataset.details)}const tech=e.target.closest('[data-tech]');if(tech){state.technology=tech.dataset.tech;$('#detail').close();if(state.source==='github')useCatalog();else render()}const rank=e.target.closest('[data-ribbon-rank]');if(rank){ribbonModes[rank.dataset.ribbonCategory]=rank.dataset.ribbonRank;render()}const all=e.target.closest('[data-view-all]');if(all){state.source='github';state.category=all.dataset.viewAll;$('#sort').value=all.dataset.rank;useCatalog()}const gallery=e.target.closest('[data-gallery]');if(gallery){detailImage=Number(gallery.dataset.gallery);showDetails(gallery.dataset.repo)}const cat=e.target.closest('[data-category]');if(cat){state.category=cat.dataset.category;if(state.source==='github'&&state.view==='discover')useCatalog();else render()}const nav=e.target.closest('[data-view]');if(nav){if(state.view!==nav.dataset.view)A.track('page_view');state.view=nav.dataset.view;if(state.view==='collection'){searchToken++;state.loading=false}$('#status').textContent='';render()}if(e.target.closest('#reset-filters')){state.category='All projects';state.technology='All technologies';state.provider='all';$('#provider').value='all';state.query='';$('#search').value='';$('#demos').checked=false;render();if(state.source==='github'&&state.view==='discover')useCatalog()}});

$('#curated').onclick=()=>{state.source='curated';state.query='';$('#search').value='';visibleLimit=48;searchToken++;state.loading=false;$('#status').textContent='';render()};$('#github').onclick=()=>{state.source='github';useCatalog()};
$('#search').oninput=e=>{clearTimeout(timer);if(e.target.value.trim())timer=setTimeout(()=>A.track('search'),700);state.query=e.target.value;if(state.query)state.source='github';useCatalog()};
$('#demos').onchange=()=>useCatalog();$('#provider').onchange=e=>{state.provider=e.target.value;useCatalog()};$('#clear-source').onclick=()=>{state.provider='all';$('#provider').value='all';useCatalog()};$('#sort').onchange=()=>{if(state.view==='discover')state.source='github';useCatalog()};$('#load-more').onclick=()=>{visibleLimit+=48;render()};$('#search-external').onclick=()=>discover(Boolean(state.remote&&hasMore()));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#more-filters').open){$('#more-filters').open=false;$('#more-filters summary').focus()}if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
$('#hero-track').onscroll=()=>{const track=$('#hero-track');if(track.children.length<2)return;const stride=track.children[1].offsetLeft-track.children[0].offsetLeft;heroIndex=Math.min(track.children.length-1,Math.max(0,Math.round(track.scrollLeft/stride)))};$('#hero-track').onkeydown=e=>{if(e.target===$('#hero-track')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();moveHero(e.key==='ArrowRight'?1:-1)}};
render();loadCatalog();loadEditorial();if(new URL(location.href).searchParams.get('signin')==='failed'){toast('GitHub sign-in could not be completed. Please try again.');history.replaceState(null,'','/')}

document.addEventListener('error',e=>{if(e.target.matches?.('.project-preview, .hero-visual img'))e.target.remove();else if(e.target.matches?.('.detail-preview')){e.target.hidden=true;toast('This preview image is temporarily unavailable.')}},true);
